function beta_media_list(array $payload, $media_path): array {
    unset($payload['html']);
    $files = [];
    foreach (media_scan_library_files($media_path) as $f) {
        $full = $media_path . '/' . $f;
        if (!is_file($full)) continue;
        $files[] = ['path' => $f, 'size' => (int) filesize($full), 'type' => media_file_type($f), 'preview' => media_preview_kind($f), 'mtime' => (int) filemtime($full)];
    }
    $payload['files'] = $files;
    $payload['base_url'] = $GLOBALS['media_base_url'] ?? '';
    return $payload;
}


