            if ($result['old_base'] !== $result['old']) {
                upload_rename_update_refs($db, $result['old_base'], $result['new_base']);
            }
            $db->commit();
            $status .= t('upload_rename_success', [htmlspecialchars($result['new'])]) . "<br>";
